def rank_people(n, scores):
    ranks = [None] * n
    max_score = -float('inf')
    count_max_score = 0

    for i in range(n):
        if scores[i] > max_score:
            max_score = scores[i]
            count_max_score = 1
        elif scores[i] == max_score:
            count_max_score += 1

    current_rank = 1
    for i in range(n):
        if ranks[i] is None:
            ranks[i] = current_rank
            current_rank += count_max_score

    return ranks

# Read input
n = int(input())
scores = list(map(int, input().split()))

# Process and print output
ranks = rank_people(n, scores)
for rank in ranks:
    print(rank)

def main():
    n = int(input())
    scores = list(map(int, input().split()))

    ranks = [None] * n

    for score in sorted(scores, reverse=True):
        count = scores.count(score)
        for i in range(count):
            if ranks[i] is None:
                ranks[i] = len(ranks) + 1

    for rank in ranks:
        print(rank)

if __name__ == "__main__":
    main()
